r_v2","dest":"c","legacyId":"1150212394355928","vars":["first","link"],"linkMode":"body","approvedStatus":"APPROVED","category":"MARKETING"}},"entry":{"default":{"path":"B","step":"NEW"},"quizDone":{"path":"D","step":"QUIZ"}},"sequences":{"B":[{"code":"M1","next":{"minutes":5}},{"code":"M2","next":{"hours":3},"thenPath":"C"}],"C":[{"code":"M3","next":{"days":1,"at":"10:00"}},{"code":"M4","next":{"days":2,"at":"10:00"}},{"code":"M5","next":{"days":4,"at":"10:00"}},{"code":"M6","next":{"days":14},"thenPath":"L"}],"D":[{"code":"M7","next":{"days":1}},{"code":"M8","next":{"days":2}},{"code":"M9","next":{"days":14},"thenPath":"L"}],"G":[{"code":"M12","next":{"days":3}},{"code":"M13","next":{"days":5}},{"code":"M14","next":{"days":11}},{"code":"M15","next":{"days":14},"thenPath":"L"}],"L":[]},"quizUpgrade":{"fromPaths":["B","C"],"to":{"path":"D","step":"QUIZ"}},"meeting":{"booked":"M10","reminder":"M10R","noShow":"M11","after":{"path":"G","step":"MET","next":{"days":2,"at":"10:00"}},"noShowLimit":2,"holdPath":"L"},"rules":{"onePerDayPaths":["C","D","G"],"sameDayAllowed":["M2","M3","M7"],"holdDays":14},"links":{"q":"https://refi.excelentfinance.com/?utm_source=whatsapp&utm_medium=funnel&utm_campaign=refi_funnel#check","c":"https://calendly.com/excellnet/15min","g":"https://share.google/L6zPPGazOqwdvB1pH","m":"https://www.midrag.co.il/SpCard/Sp/94658","b":"https://www.bizreviews.co.il/provider/peled-yoram"},"handoff":{"heatAtLeast":70,"onReply":true,"onBooking":true},"kpiTargets":{"costPerPayingClient":1400,"costPerMeeting":350},"meta":{"campaignIds":["120252891592490603"],"adAccount":"287081049104797"},"groups":{"meetings":"group_mm883gr6"},"identity":{"profile":"excelent_finance","nameInMessages":"יורם פלד","contactPhone":"excelent_contact","testPhones":["excelent_contact","backup"],"approved":true,"approvedBy":"יורם","approvedAt":"2026-10-20","source":"הנחיות יורם בשיחה מ 20.10.2026"},"linkTokenExamples":["a1b2c3d4e5q"]};
const DEST = CFG.links, C = CFG.columns;
const EXAMPLES = (CFG.linkTokenExamples || []).map(x => String(x).toLowerCase());
const raw = String(($('Link').first().json.query || {}).c || '').trim().toLowerCase();
const page = $('Items').first().json.data.boards[0].items_page;
if (page.cursor) throw new Error('Monday result truncated: do not attribute clicks from a partial lead list');
const items = page.items;
const m = raw.match(/^([a-z0-9]{10}|[a-z0-9]{20}|[a-z0-9]{32})([a-z])$/);
let token = '', dest = '', lead = null, reason = '';
if (!m) reason = 'bad format';
else if (EXAMPLES.includes(raw) || EXAMPLES.includes(m[1])) reason = 'template example value';
else {
  token = m[1]; dest = m[2];
  const owners = items.filter(it => (it.column_values.find(c => c.id === C.token) || {}).text === token);
  if (owners.length === 1) { const it = owners[0]; const cv = {}; for (const c of it.column_values) cv[c.id] = c; lead = { it, cv }; }
  else reason = owners.length ? 'token not unique' : 'unknown token';
}
// the destination letter is trusted only for a known lead; otherwise the campaign landing page
if (!lead || !DEST[dest]) dest = 'q';
let url = DEST[dest];
const out = { url, found: !!lead, dest, reason, campaign: CFG.id };
if (lead) {
  if (dest === 'q') out.url = url.replace('#', (url.includes('?') ? '&' : '?') + 't=' + token + '#');
  let st;
  const storedState = lead.cv[C.state]?.text;
  try { st = storedState ? JSON.parse(storedState) : null; } catch (e) { st = null; }
  const obj = v => !!v && typeof v === 'object' && !Array.isArray(v);
  const heatValue = Number(lead.cv[C.heat]?.text || 0);
  if (!obj(st) ||
      ('opens' in st && (!obj(st.opens) || Object.entries(st.opens).some(([d,n])=>!Object.hasOwn(DEST,d)||!Number.isSafeInteger(n)||n<1))) ||
      ('clicks' in st && !Array.isArray(st.clicks)) ||
      ('clickHeat' in st && (!Number.isInteger(st.clickHeat)||st.clickHeat<0||st.clickHeat>15||st.clickHeat%5!==0)) ||
      (st.opens && Object.keys(st.opens).length && !Object.hasOwn(st,'clickHeat')) ||
      !Number.isFinite(heatValue) || heatValue<0) {
    // The destination still works, but no heat or engagement state is written over corrupted state.
    return [{ json: { url: out.url, found: false, dest, reason: 'invalid stored lead state', campaign: CFG.id } }];
  }
  const status=lead.cv[C.status]?.text;
  if(st.tokenRevoked===true||['הסר','נעצר','לקוח'].includes(status)||
      ((token.length===32||Object.hasOwn(st,'tokenExpiresAt'))&&
       (!Number.isFinite(st.tokenExpiresAt)||st.tokenExpiresAt<=Date.now()))) {
    return [{json:{url,found:false,dest,reason:'token expired or revoked',campaign:CFG.id}}];
  }
  st.opens = st.opens || {};
  const now = Date.now();
  const firstOfType = !st.opens[dest];
  st.opens[dest] = (st.opens[dest] || 0) + 1;
  st.clicks = (st.clicks || []).concat([{ d: dest, at: new Date(now).toISOString(), campaign: CFG.id }]).slice(-20);
  // heat: +5 only for the first click on each destination type, at most 15 in total from clicks
  let heat = Number(lead.cv[C.heat]?.text || 0);
  const before = heat;
  st.clickHeat = st.clickHeat || 0;
  if (firstOfType && st.clickHeat < 15) { heat += 5; st.clickHeat += 5; }
  const cols = { [C.state]: { text: JSON.stringify(st) } };
  if (heat !== before) cols[C.heat] = String(heat);
  out.itemId = lead.it.id; out.colsJson = JSON.stringify(cols);
  out.notify = before < CFG.handoff.heatAtLeast && heat >= CFG.handoff.heatAtLeast && (lead.cv[C.path]?.text || '') !== 'E';
  out.notifyText = 'משפך ' + CFG.name + ': הליד הגיע לציון חום ' + heat + ' ומוכן לשיחה. לחץ על: ' + dest;
  out.meId = $('Items').first().json.data.me.id;
}
return [{ json: out }];

// n8n Code node "Items": validate every page before any attribution or write.
const pages = $input.all();
if (!pages.length) throw new Error('Monday returned no pages');
const items = [], ids = new Set(), cursors = new Set();
let me;
for (let i = 0; i < pages.length; i++) {
  const body = pages[i].json;
  if (body.errors?.length) throw new Error('Monday GraphQL errors: refusing partial results');
  const data = body.data;
  const page = data?.boards?.[0]?.items_page;
  if (!data?.me?.id || !Array.isArray(page?.items) || !Object.hasOwn(page, 'cursor') ||
      (page.cursor !== null && (typeof page.cursor !== 'string' || !page.cursor))) {
    throw new Error('Invalid Monday page');
  }
  if (me && me.id !== data.me.id) throw new Error('Monday identity changed between pages');
  me = data.me;
  if (i < pages.length - 1 && !page.cursor) throw new Error('Unexpected page after terminal cursor');
  if (page.cursor && cursors.has(page.cursor)) throw new Error('Repeated Monday cursor');
  if (page.cursor) cursors.add(page.cursor);
  if (i === pages.length - 1 && page.cursor) throw new Error('Monday result truncated at pagination limit');
  for (const item of page.items) {
    if (!item.id || !Array.isArray(item.column_values) || ids.has(String(item.id))) {
      throw new Error('Invalid or duplicate Monday item across pages');
    }
    ids.add(String(item.id)); items.push(item);
  }
}
return [{json:{data:{me,boards:[{items_page:{items,cursor:null}}]}}}];
